// 이번 실행에서 만든 전체 객체 수를 세요.
class Ticket {
    static int created = 0;
    Ticket() {
        // 공유 카운터의 갱신 방법을 비교해요.
        created++;
    }
}

class Main {
    public static void main(String[] args) {
        // 준비된 개수만큼 객체를 만들어요.
        int count = 2;
        for (int i = 0; i < count; i++) {
            Ticket next = new Ticket();
        }
        System.out.println(Ticket.created);
    }
}
